#!/usr/bin/env python3
"""Measure all AQ properties once per single-fault RTL mutant with JasperGold.

The output matrix is consumed by evaluate.py. This does not use check_cov's
internal mutants: each manifest entry supplies an explicit replacement RTL.
"""

from __future__ import annotations

import argparse
import csv
import hashlib
import json
import re
import subprocess
import tempfile
import sys
from pathlib import Path

from evaluate import read_manifest
sys.path.insert(0,str(Path(__file__).resolve().parents[1]/"aq"))
from jasper_reset import reset_command


PROPERTY_LINE = re.compile(r"^FH_PROPERTY\t([^\t]+)\t([^\t]+)$", re.MULTILINE)


def tcl_atom(value: str | Path) -> str:
    value = str(value).replace("\\", "/").replace("{", "\\{").replace("}", "\\}")
    return "{" + value + "}"


def tcl_list(values: list[str | Path]) -> str:
    return " ".join(tcl_atom(x) for x in values)


def resolve(value: str, base: Path) -> Path:
    path = Path(value)
    return (path if path.is_absolute() else base / path).resolve()


def target_selection_tcl(expected: list[str], *, allow_empty: bool = False, target_scope: str = "") -> str:
    """Select exact final labels inside the configured bound checker instance.

    One label must map to exactly one elaborated property. Multiple checker
    instances are ambiguous and are never silently merged or counted twice.
    Named procedural/generate scopes between that instance and label are valid.
    """
    if (not expected and not allow_empty) or len(set(expected)) != len(expected):
        raise ValueError("Expected target assertion labels must be nonempty and unique")
    return f'''proc fh_property_matches_target {{property scope label}} {{
    # Literal comparisons keep scope names with bracketed generate indices safe.
    set suffix ".$label"
    set has_leaf [expr {{[string length $property] >= [string length $suffix] &&
        [string range $property end-[expr {{[string length $suffix]-1}}] end] eq $suffix}}]
    if {{$scope eq ""}} {{
        set embedded_suffix "::$label"
        return [expr {{$property eq $label || $has_leaf ||
            ([string length $property] >= [string length $embedded_suffix] &&
            [string range $property end-[expr {{[string length $embedded_suffix]-1}}] end] eq $embedded_suffix)}}]
    }}
    if {{!$has_leaf}} {{ return 0 }}
    set parent [string range $property 0 end-[string length $suffix]]
    set start 0
    while {{[set index [string first $scope $parent $start]] >= 0}} {{
        set after [expr {{$index + [string length $scope]}}]
        set before_ok [expr {{$index == 0 || [string index $parent [expr {{$index-1}}]] eq "." ||
            ($index >= 2 && [string range $parent [expr {{$index-2}}] [expr {{$index-1}}]] eq "::")}}]
        set after_ok [expr {{$after == [string length $parent] || [string index $parent $after] eq "."}}]
        if {{$before_ok && $after_ok}} {{ return 1 }}
        set start [expr {{$index+1}}]
    }}
    return 0
}}
set FH_EXPECTED [list {tcl_list(expected)}]
set FH_TARGET_SCOPE {tcl_atom(target_scope)}
set FH_ALL_ASSERTIONS [get_property_list -include {{type assert}}]
foreach item $FH_ALL_ASSERTIONS {{ puts "FH_INVENTORY\\t$item" }}
set properties [list]
foreach label $FH_EXPECTED {{
    set matches [list]
    foreach item $FH_ALL_ASSERTIONS {{
        if {{[fh_property_matches_target $item $FH_TARGET_SCOPE $label]}} {{
            lappend matches $item
        }}
    }}
    if {{[llength $matches] != 1}} {{
        error "target assertion mapping failed: label=$label scope=$FH_TARGET_SCOPE matches=[llength $matches] names=$matches inventory=$FH_ALL_ASSERTIONS"
    }}
    lappend properties [lindex $matches 0]
    puts "FH_TARGET\\t$label\\t[lindex $matches 0]"
}}
puts "FH_ASSERTION_COUNTS total=[llength $FH_ALL_ASSERTIONS] target=[llength $properties] background=[expr {{[llength $FH_ALL_ASSERTIONS]-[llength $properties]}}]"
'''


def make_tcl(config: dict, rtl_files: list[Path], assertion_file: Path, bind_files: list[Path],
             include_dirs: list[Path], defines: list[str], *, check_paths: bool = True,
             expected: list[str] | None = None) -> str:
    for path in [*rtl_files, assertion_file, *bind_files, *include_dirs]:
        if check_paths and not path.exists():
            raise ValueError(f"required source/include path missing: {path}")
    clock_mode = config.get("clock_mode", "clocked")
    if clock_mode not in {"clocked", "none"}:
        raise ValueError("clock_mode must be clocked or none")
    if clock_mode == "clocked" and not config.get("clock"):
        raise ValueError("clocked design needs config.clock")
    options = [f"+incdir+{x}" for x in include_dirs] + [f"+define+{x}" for x in defines]
    return f'''# Generated by collect_jasper.py; one RTL mutant, all AQ assertions.
set FH_TOP {tcl_atom(config["top"])}
set FH_CLOCK_MODE {tcl_atom(clock_mode)}
set FH_RTL [list {tcl_list(rtl_files)}]
set FH_ASSERTION {tcl_atom(assertion_file)}
set FH_BIND [list {tcl_list(bind_files)}]
set FH_OPTIONS [list {tcl_list(options)}]
clear -all
if {{[catch {{
    analyze -sv {{*}}$FH_OPTIONS {{*}}$FH_RTL $FH_ASSERTION {{*}}$FH_BIND
    elaborate -top $FH_TOP
}} err]}} {{
    puts "FH_SETUP_ERROR $err"
    exit -force
}}
if {{[catch {{
    if {{$FH_CLOCK_MODE eq "none"}} {{
        clock -none
        reset -none
    }} else {{
        clock {tcl_atom(config.get("clock", ""))}
        {reset_command(config.get('reset_expression','')) if clock_mode=='clocked' else 'reset -none'}
    }}
    {target_selection_tcl(config['assertions'] if expected is None else expected,target_scope=config.get('target_scope',''))}
    prove -all
}} err]}} {{
    puts "FH_PROVE_ERROR $err"
    exit -force
}}
foreach property $properties {{
    if {{[catch {{set raw [get_property_info $property -list status]}} err]}} {{
        puts "FH_PROPERTY\\t$property\\tSTATUS_QUERY_ERROR"
        continue
    }}
    if {{![catch {{set status [dict get $raw status]}}]}} {{
        # status extracted from a dict
    }} elseif {{[llength $raw] >= 2 && [string tolower [lindex $raw 0]] eq "status"}} {{
        set status [lindex $raw 1]
    }} else {{
        set status $raw
    }}
    puts "FH_PROPERTY\\t$property\\t[string tolower [string trim $status]]"
}}
puts "FH_DONE"
flush stdout
exit -force
'''


def classify(raw: str) -> str:
    value = raw.lower().strip()
    if "cex" in value:
        return "CEX"
    if "bounded_proven" in value:
        return "UNKNOWN"
    if "proven" in value:
        return "PROVEN"
    return "UNKNOWN"


def parse_log(text: str, expected: list[str]) -> dict[str, str]:
    if not re.search(r"^FH_DONE$", text, re.MULTILINE):
        raise ValueError("Jasper did not finish cleanly; inspect run.log")
    raw_properties = PROPERTY_LINE.findall(text)
    result: dict[str, str] = {}
    for name, status in raw_properties:
        matching = [a for a in expected if name == a or name.endswith("." + a)]
        if len(matching) != 1 or matching[0] in result:
            raise ValueError(f"active property cannot be mapped uniquely to AQ: {name}")
        result[matching[0]] = classify(status)
    if len(raw_properties) != len(expected) or set(result) != set(expected):
        raise ValueError(f"active property count/mapping mismatch: expected={len(expected)}, got={len(raw_properties)}")
    return result


def input_fingerprint(tcl: str, config: dict, source_files: list[Path], include_dirs: list[Path]) -> str:
    digest = hashlib.sha256(tcl.encode("utf-8"))
    digest.update(json.dumps(config, sort_keys=True).encode("utf-8"))
    files = set(source_files)
    for directory in include_dirs:
        files.update(p for p in directory.rglob("*") if p.is_file() and p.suffix in {".sv", ".v", ".svh", ".vh"})
    for path in sorted(files):
        digest.update(str(path).encode("utf-8"))
        digest.update(hashlib.sha256(path.read_bytes()).digest())
    return digest.hexdigest()


def write_matrix(path: Path, rows: list[dict[str, str]]) -> None:
    temporary = path.with_suffix(".csv.tmp")
    with temporary.open("w", newline="", encoding="utf-8") as handle:
        writer = csv.DictWriter(handle, fieldnames=["assertion_id", "mutant_id", "status"])
        writer.writeheader()
        writer.writerows(rows)
    temporary.replace(path)


def collect(config_path: Path, manifest_path: Path, output: Path, *,
            cache_dir: Path | None = None, dry_run: bool = False, force: bool = False,
            reuse_only: bool = False, retry_unknown: bool = False) -> dict:
    from shared_results import Checker, ResultCache, environment, job_key, save_json, STATUSES
    config_path, manifest_path, output = config_path.resolve(), manifest_path.resolve(), output.resolve()
    config = json.loads(config_path.read_text(encoding="utf-8"))
    manifest = json.loads(manifest_path.read_text(encoding="utf-8"))
    assertions, families = read_manifest(manifest_path)
    root = resolve(config.get("project_root", "."), config_path.parent)
    golden_rtl = [resolve(x, root) for x in config["rtl_files"]]
    assertion_file = resolve(config["assertion_file"], root)
    binds = [resolve(x, root) for x in config.get("bind_files", [])]
    includes = [resolve(x, root) for x in config.get("include_dirs", [])]
    checker = Checker(assertion_file.read_text(), assertions, str(assertion_file))
    env = environment(config, root, checker, assertion_file)
    cache = ResultCache(cache_dir or output.parent / "_shared_results")
    output.mkdir(parents=True, exist_ok=True)
    stats = {"mutants": len(manifest["mutants"]), "assertions": len(assertions),
             "golden_proof_sessions": 0, "jasper_sessions": 0, "cached_cells": 0,
             "measured_cells": 0, "missing_cells": 0, "cache_dir": str(cache.root)}
    rows = []
    ids = set()
    for item in manifest["mutants"]:
        job_id = item["id"]
        if not re.fullmatch(r"[A-Za-z0-9_.-]+", job_id) or job_id == "golden" or job_id in ids:
            raise ValueError(f"unsafe or duplicate mutant id: {job_id}")
        ids.add(job_id)
        replaced = resolve(item["replace"], root)
        mutant = resolve(item["file"], manifest_path.parent)
        if replaced not in golden_rtl or not mutant.is_file():
            raise ValueError(f"mutant {job_id}: invalid replacement or missing RTL")
        index = golden_rtl.index(replaced)
        rtl = [mutant if x == replaced else x for x in golden_rtl]
        key = job_key(env, checker, index, mutant.read_bytes(), mutant)
        run_dir = output / "runs" / job_id
        run_dir.mkdir(parents=True, exist_ok=True)
        cache_path = run_dir / "result.json"
        # Serialize work for this mutant/context across simultaneous collectors.
        with cache.lock(key, work=True):
            if cache_path.is_file() and not force and not dry_run:
                old = json.loads(cache_path.read_text())
                properties = old.get("properties", {})
                fresh = (old.get("context_sha256") == key
                         and old.get("assertion_keys") == checker.keys)
                if not fresh and old.get("input_sha256"):
                    full_tcl = make_tcl(config, rtl, assertion_file, binds, includes, config.get("defines", []))
                    fresh = old["input_sha256"] == input_fingerprint(
                        full_tcl, config, [*rtl, assertion_file, *binds], includes)
                if fresh and set(properties) == set(assertions) and set(properties.values()) <= STATUSES:
                    cache.put(key, checker, properties, str(cache_path))
            result = {} if force else cache.lookup(key, checker, retry_unknown)
            missing = [name for name in assertions if name not in result]
            stats["cached_cells"] += len(result)
            measured = []
            if missing:
                if reuse_only and not dry_run:
                    stats["missing_cells"] += len(missing)
                    save_json(output / "reuse_stats.json", stats)
                    raise RuntimeError(f"no cached results for {job_id}: {missing}; --reuse-only never launches Jasper")
                # Whole-checker fallback handles syntax we cannot split safely.
                if checker.partial:
                    representatives = {}
                    for name in missing:
                        representatives.setdefault(checker.keys[name], name)
                    measured = list(representatives.values())
                else:
                    measured = assertions
                attempt = run_dir if dry_run else Path(tempfile.mkdtemp(prefix="attempt_", dir=run_dir))
                pending = assertion_file
                if set(measured) != set(assertions):
                    pending = attempt / "pending" / assertion_file.name
                    pending.parent.mkdir(parents=True, exist_ok=True)
                    pending.write_text(checker.subset(measured))
                tcl_path = attempt / "run.tcl"
                tcl_path.write_text(make_tcl(config, rtl, pending, binds, includes, config.get("defines", []),expected=measured))
                if dry_run:
                    print(f"DRY-RUN {job_id}: {len(result)} cached, {len(measured)} to prove; {tcl_path}")
                    continue
                log_path = attempt / "run.log"
                print(f"START {job_id}: {len(result)} cached, prove {len(measured)} assertions; {log_path}", flush=True)
                try:
                    with log_path.open("w") as handle:
                        completed = subprocess.run([config.get("jasper_executable", "jg"), "-batch", str(tcl_path)],
                            cwd=attempt, stdout=handle, stderr=subprocess.STDOUT, text=True,
                            timeout=int(config.get("timeout_seconds", 14400)), check=False)
                except subprocess.TimeoutExpired as exc:
                    raise RuntimeError(f"Jasper timeout on {job_id}; {log_path}") from exc
                if completed.returncode != 0:
                    raise RuntimeError(f"Jasper failed on {job_id} (exit {completed.returncode}); {log_path}")
                observed = parse_log(log_path.read_text(errors="replace"), measured)
                cache.put(key, checker, observed, str(log_path))
                # Keep previous definitive evidence if a retry only yields UNKNOWN.
                result = cache.lookup(key, checker)
                stats["jasper_sessions"] += 1
                stats["measured_cells"] += len(measured)
            if dry_run:
                print(f"DRY-RUN REUSE {job_id}: all {len(result)} cells cached")
                continue
            if set(result) != set(assertions):
                raise ValueError(f"incomplete result for {job_id}")
            if cache_path.is_file():
                previous = cache_path.read_bytes()
                if json.loads(previous).get("schema") != 2:
                    from shared_results import sha
                    history = run_dir / "history" / ("result_" + sha(previous) + ".json")
                    if not history.exists():
                        history.parent.mkdir(parents=True, exist_ok=True)
                        history.write_bytes(previous)
            save_json(cache_path, {"schema": 2, "context_sha256": key,
                "assertion_keys": checker.keys, "properties": result,
                "measured_assertions": measured, "shared_cache": str(cache.path(key))})
            rows.extend({"assertion_id": name, "mutant_id": job_id, "status": result[name]}
                        for name in assertions)
            write_matrix(output / "matrix.csv", rows)
            save_json(output / "reuse_stats.json", stats)
            print(f"DONE {job_id}: reused={len(assertions) - len(measured)}, measured={len(measured)}", flush=True)
    if not dry_run:
        write_matrix(output / "matrix.csv", rows)
    save_json(output / "reuse_stats.json", stats)
    print(f"COLLECTION: {stats['jasper_sessions']} mutant sessions, {stats['cached_cells']} cached cells; no golden proof")
    return stats


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--config", type=Path, required=True)
    parser.add_argument("--manifest", type=Path, required=True)
    parser.add_argument("--output", type=Path, required=True)
    parser.add_argument("--cache-dir", type=Path, help="shared across models/trials; defaults beside output")
    parser.add_argument("--dry-run", action="store_true")
    parser.add_argument("--force", action="store_true", help="remeasure this AQ, ignoring shared evidence")
    parser.add_argument("--reuse-only", action="store_true", help="fail on missing cells, never launch Jasper")
    parser.add_argument("--retry-unknown", action="store_true", help="retry cached UNKNOWN cells only")
    args = parser.parse_args()
    collect(args.config, args.manifest, args.output, cache_dir=args.cache_dir,
            dry_run=args.dry_run, force=args.force, reuse_only=args.reuse_only,
            retry_unknown=args.retry_unknown)


if __name__ == "__main__":
    main()
